	shortDescription = "Symbol Tree",
	description = "This plugin shows the symbols from the program " +
			"in a tree hierarchy.  All symbols (except for the global namespace symbol) " +
			"have a parent symbol.  From the tree, symbols can be renamed, deleted, or " +
			"reorganized.",
	eventsConsumed = { typeof(ProgramActivatedPluginEvent), typeof(ProgramLocationPluginEvent), typeof(ProgramClosedPluginEvent) },
	servicesProvided = { typeof(SymbolTreeService) }
) */
//@formatter:on
public class SymbolTreePlugin : Plugin, SymbolTreeService {

	public static readonly string OPTIONS_CATEGORY = "Symbol Tree";
	public static readonly string OPTION_NAME_GROUP_THRESHOLD = "Group Threshold";

	private SymbolTreeProvider connectedProvider;
	private List<SymbolTreeProvider> disconnectedProviders = new();
	private Program program;
	private GoToService goToService;
	private bool processingGoTo;

	private OptionsChangeListener optionsListener = new SymbolTreeOptionsListener();
	private int nodeGroupThreshold = 200;

	public SymbolTreePlugin(PluginTool tool) : base(tool)
    {

		connectedProvider = new SymbolTreeProvider(tool, this);
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		if (@event is ProgramActivatedPluginEvent) {
			ProgramActivatedPluginEvent ev = (ProgramActivatedPluginEvent) @event;
			Program oldProgram = program;
			program = ev.getActiveProgram();
			if (oldProgram != null) {
				connectedProvider.programDeactivated(oldProgram);
			}

			connectedProvider.setProgram(program);
		}
		else if (@event is ProgramClosedPluginEvent) {
			programClosed(((ProgramClosedPluginEvent) @event).getProgram());
		}
		else if (@event is ProgramLocationPluginEvent) {
			if (processingGoTo) {
				return; // no bouncing!!
			}

			ProgramLocation loc = ((ProgramLocationPluginEvent) @event).getLocation();
			connectedProvider.locationChanged(loc);

			foreach (SymbolTreeProvider provider in disconnectedProviders) {
				provider.locationChanged(loc);
			}
		}
	}

	private void programClosed(Program p) {

		connectedProvider.programClosed(p);

		List<SymbolTreeProvider> copy = new(disconnectedProviders);
		foreach (SymbolTreeProvider provider in copy) {
			if (provider.getProgram() == p) {
				closeDisconnectedProvider(provider);
			}
		}
	}

	void closeDisconnectedProvider(SymbolTreeProvider provider) {
		disconnectedProviders.remove(provider);
		tool.removeComponentProvider(provider);
		provider.dispose();
	}

	/* @Override */
	protected void init() {
		goToService = tool.getService(typeof(GoToService));

		initializeOptions();
	}

	private void initializeOptions() {

		ToolOptions options = tool.getOptions(OPTIONS_CATEGORY);
		options.addOptionsChangeListener(optionsListener);

		HelpLocation help = new HelpLocation("SymbolTreePlugin", "GroupNode");
		options.registerOption(OPTION_NAME_GROUP_THRESHOLD, nodeGroupThreshold, help,
			"The max number of children before nodes are organized by name");

		nodeGroupThreshold = options.getInt(OPTION_NAME_GROUP_THRESHOLD, nodeGroupThreshold);
	}

	/* @Override */
	protected void dispose() {
		tool.removeComponentProvider(connectedProvider);
		connectedProvider.dispose();
		program = null;

		List<SymbolTreeProvider> copy = new(disconnectedProviders);
		foreach (SymbolTreeProvider provider in copy) {
			closeDisconnectedProvider(provider);
		}
	}

	/* @Override */
	public void readConfigState(SaveState saveState) {
		connectedProvider.readConfigState(saveState);
	}

	/* @Override */
	public void writeConfigState(SaveState saveState) {
		connectedProvider.writeConfigState(saveState);
	}

	public void goTo(Symbol symbol) {

		SymbolType type = symbol.getSymbolType();
		if (type.isNamespace() && type != SymbolType.FUNCTION) {
			tool.setStatusInfo("Can not navigate to " + (symbol.isExternal() ? "external " : "") +
				type.toString() + " symbol: " + symbol.getName());
			return;
		}

		bool success = false;
		string reason = "";
		if (goToService != null) {
			processingGoTo = true;
			try {
				ProgramLocation loc = symbol.getProgramLocation();
				if (symbol.getAddress().isExternalAddress()) {
					goToService.goTo(symbol.getAddress(), program);
					return; // let GoTo service provide status messages
				}
				else if (loc != null) {
					reason = " (not in-memory)";
					success = goToService.goTo(loc);
				}
			}
			finally {
				processingGoTo = false;
			}
		}

		if (!success) {
			tool.setStatusInfo("Can not navigate to " + (symbol.isExternal() ? "external " : "") +
				type.toString() + " symbol: " + symbol.getName() + reason);
		}
	}

	public void goTo(ExternalLocation extLoc) {
		goToService.goToExternalLocation(extLoc, false);
	}

	public Program getProgram() {
		return program;
	}

	SymbolTreeProvider getProvider() {
		return connectedProvider;
	}

	public DisconnectedSymbolTreeProvider createNewDisconnectedProvider(Program p) {
		DisconnectedSymbolTreeProvider newProvider =
			new DisconnectedSymbolTreeProvider(tool, this, p);
		disconnectedProviders.add(newProvider);
		tool.showComponentProvider(newProvider, true);
		return newProvider;
	}

	/* @Override */
	public void selectSymbol(Symbol symbol) {
		connectedProvider.selectSymbol(symbol);

	}

	void setNodeGroupThreshold(int threshold) {
		nodeGroupThreshold = threshold;
	}

	int getNodeGroupThreshold() {
		return nodeGroupThreshold;
	}

	private class SymbolTreeOptionsListener : OptionsChangeListener {

		/* @Override */
		public void optionsChanged(ToolOptions options, string optionName, object oldValue,
				object newValue)
    {

			if (OPTION_NAME_GROUP_THRESHOLD.equals(optionName)) {
				nodeGroupThreshold = (int) newValue;
				connectedProvider.rebuildTree();
				foreach (SymbolTreeProvider provider in disconnectedProviders) {
					provider.rebuildTree();
				}
			}
		}

	}
}
